import type { EnvKind, TargetKind } from '../core/types';

/**
 * Central registry of procedural texture keys generated by the Boot scene.
 * Pure strings — usable from both Phaser layer and tests.
 */

export function birdKey(kind: TargetKind, frame = 0): string {
  return `bird_${kind}_${frame}`;
}

export function flapAnim(kind: TargetKind): string {
  return `flap_${kind}`;
}

export const ANIMATED_BIRDS: TargetKind[] = [
  'flatterer',
  'swift',
  'corkscrew',
  'gold',
  'mist',
  'decoy',
  'swarm',
  'glider',
  'storm',
];

export function envKey(kind: EnvKind): string {
  return `env_${kind}`;
}

